    private ProperFractionFormat formatter;

    @Before
    public void setUp() {
        formatter = new ProperFractionFormat();
    }





    @Test
    public void testParseWithWhitespace() {
        ParsePosition pos = new ParsePosition(0);
        // "whole num / den"
        Fraction result = formatter.parse(" 1  2 / 3 ", pos);
        // Calculation: w=1, n=2, d=3 -> ((1*3)+2) = 5. Sign(1)=1. Result 5/3
        // Note: The implementation uses Math.abs(w)*d + n. 
        // For 1 2/3 -> w=1, n=2, d=3 -> (1*3 + 2) = 5. Result 5/3.
        assertEquals(new Fraction(5, 3), result);
    }


















}

